<h2>Calculate property DSCR</h2><p class="lead">Calculate debt service coverage ratio from net operating income and annual debt service.</p><div class="notice">Use the lender’s NOI and debt-service definitions for underwriting. This calculator does not determine loan eligibility.</div><div class="form-grid"><div class="field"><label for="noi">Annual net operating income (NOI)</label><input id="noi" type="number" value="900000" min="0" step="any"></div><div class="field"><label for="debt">Annual debt service</label><input id="debt" type="number" value="650000" min="0.01" step="any"></div><div class="field"><label for="target">Target DSCR</label><input id="target" type="number" value="1.25" min="0.01" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>DSCR</span><strong id="dscr">—</strong></div><div class="metric"><span>NOI after debt service</span><strong id="surplus">—</strong></div><div class="metric"><span>NOI required at target</span><strong id="required">—</strong></div><div class="metric"><span>NOI headroom vs target</span><strong id="headroom">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('dscr').textContent='—';$('surplus').textContent='—';$('required').textContent='—';$('headroom').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const n=num('noi'),d=num('debt'),t=num('target');if(!(n>=0&&d>0&&t>0))throw 0;const ratio=n/d,req=d*t,head=n-req;$('dscr').textContent=fmt(ratio,3)+'×';$('surplus').textContent=fmt(n-d,2);$('required').textContent=fmt(req,2);$('headroom').textContent=(head>=0?'+':'')+fmt(head,2);$('note').textContent='Freddie Mac defines debt coverage as NOI divided by annual debt service. Lenders can apply their own NOI adjustments, reserves and minimum DSCR requirements.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
